-- Records the real BusinessSignals classifier + check_business_signals
-- agent tool (resolves the Priority Engine's previously-unmet
-- BusinessSignals dependency), plus two honest, separately-tracked findings
-- of real, tested engines with zero production callers. Applied live via
-- Supabase MCP on 2026-09-02; this file makes that reproducible from a
-- fresh database.
insert into public.capability_registry
  (capability_key, name, description, category, skill, agent_tool_name, package_or_module, department, connection, required_permission, read_write, tenant_scope, cost_profile, risk, verification_method, status, status_notes, external_blocker, last_verified_at, last_verified_by)
values
  ('capability:business_signals_classifier', 'Real BusinessSignals classifier + check_business_signals agent tool', 'Resolves the Priority Engine''s previously-unmet BusinessSignals dependency (packages/workforce-core diagnoseBusinessGrowth accepts an optional businessSignals input that nothing in the app ever computed from real data -- every call site either omitted it or would have had to fabricate one). New lib/agent-core/business-signals.ts computes hasWebsite, searchVisibilityStrength, crmFollowUpStrength, monthlyInquiries, and postContactConversionStrength live from real site_projects/search_opportunities/crm_leads rows, each populated field carrying a real row id in signalEvidenceIds; every other BusinessSignals field (websiteTrafficStrength, hasAds, medianResponseTimeHours, leadCaptureStrength, socialPresenceStrength, analyticsAttributionStrength) is left honestly undefined -- no real data source exists yet for any of them (no analytics-to-first-contact event stream, no ad-spend table, no lead-capture-form tracking). Exposed as a new read-only agent tool, check_business_signals (lib/agent-core/business-signals-tool.ts), wired into both real tool-registration points (lib/agent-core/copilot-actions.ts for Admin/Client Copilot, app/api/internal/agent/whatsapp/route.ts for WhatsApp), same resolveTenantId discipline as check_connections/check_growth_status. Deliberately does NOT call diagnoseBusinessGrowth/deriveBottlenecks directly: their shared BusinessGrowthPlannerInput also requires a real entitlementSnapshot with a full AllocationPolicy (billing/allocation data this tool has no honest source for) -- fabricating one to force the call would violate the same real-data-or-nothing rule this classifier exists to uphold. Wiring the full diagnosis/30-day-planner pipeline into a production route is a separate, larger integration that belongs with the mission-creation flow that already owns a real entitlementSnapshot -- tracked as a distinct, honestly still-open item, not claimed complete here.', 'ecosystem', null, 'check_business_signals', 'lib/agent-core/business-signals.ts, lib/agent-core/business-signals-tool.ts', 'Engineering', null, 'agent:read:research', 'read', 'tenant', 'free', 'read', 'business-signals.test.ts (new, 6 real assertions incl. small-sample-size and cross-tenant-isolation regressions), full-repo tsc --noEmit clean, lint clean, real NODE_ENV=production next build exit 0 (verified given the same-day lesson that tsc alone cannot catch a runtime module-evaluation defect)', 'REAL_EXPOSED', 'The classifier and the standalone check_business_signals tool are both genuinely live and callable via WhatsApp/Admin/Client Copilot today. The separate, heavier diagnoseBusinessGrowth/deriveBottlenecks/planBusinessGrowth pipeline (packages/workforce-core/src/planning) remains REAL_NOT_EXPOSED -- built and tested, but not called from any production route -- left as its own honestly-open item rather than folded into this one.', null, now(), 'claude_session_2026-09-02'),
  ('capability:business_growth_planner_pipeline', 'Business Growth / 30-day planner engine (diagnoseBusinessGrowth, deriveBottlenecks, planBusinessGrowth)', 'A real, mature, heavily-tested engine (packages/workforce-core/src/planning: diagnosis.ts, thirty-day-planner.ts, recommendations.ts, workflows.ts) that turns BusinessSignals + Brand Brain + entitlements into an evidence-gated diagnosis, prioritized bottlenecks, and a full 30-day workforce plan with weekly strategy and customer-facing summaries. Confirmed by grepping every real caller in the repo: planBusinessGrowth/planThirtyDayGrowth is invoked only from packages/workforce-core''s own tests and e2e harness (src/e2e/harness.ts) -- zero app/ routes, zero lib/agent-core tools, zero API endpoints call it. The new check_business_signals tool (capability:business_signals_classifier) now supplies a real, honest partial BusinessSignals input this engine could consume, but does not itself call this heavier pipeline (its BusinessGrowthPlannerInput also requires a real entitlementSnapshot with a full AllocationPolicy that no lightweight read tool can honestly source). Wiring this into a real mission-creation/plan-generation route is a genuine, separate, not-yet-done integration task.', 'ecosystem', null, null, 'packages/workforce-core/src/planning/diagnosis.ts, thirty-day-planner.ts, recommendations.ts, workflows.ts', 'Engineering', null, null, 'read', 'tenant', 'free', 'read', 'Confirmed via repo-wide grep for planBusinessGrowth/planThirtyDayGrowth/diagnoseBusinessGrowth call sites: only packages/workforce-core/src/__tests__/*, e2e/harness.ts, and packages/workforce-core''s own scenarios.ts reference it. No app/ or lib/agent-core caller exists.', 'REAL_NOT_EXPOSED', 'Real, tested engine; genuinely not reachable by any customer, staff, or agent action today. Not a fabricated gap -- verified by exhaustive grep, not assumption.', null, now(), 'claude_session_2026-09-02'),
  ('capability:revenue_ops_workflow_pipeline', 'Revenue Ops CRM/WhatsApp conversion engine (runRevenueWorkflow)', 'A real, tested engine (packages/revenue-ops/src/orchestrator.ts) that diagnoses response-time performance, builds per-lead intelligence, qualifies leads, drafts CRM follow-up plans and WhatsApp follow-up sequences, diagnoses conversion, and evaluates human-handoff -- end to end, no production sends (productionMutations/sendAttempts are always returned empty; gateCrmWrite/gateWhatsAppSend exist as separate authorization gates for whoever wires real writes in). Confirmed by repo-wide grep: runRevenueWorkflow, toBusinessGrowthSignals, and every other export of this package are referenced only by packages/revenue-ops''s own tests -- zero app/ or lib/agent-core callers exist. A real, substantial, unwired capability, not previously recorded in the registry.', 'ecosystem', null, null, 'packages/revenue-ops/src/orchestrator.ts', 'Engineering', null, null, 'read', 'tenant', 'free', 'read', 'Confirmed via repo-wide grep for runRevenueWorkflow/toBusinessGrowthSignals: only packages/revenue-ops/src/__tests__/revenue-ops.test.ts references them. No app/ or lib/ caller exists.', 'REAL_NOT_EXPOSED', 'Real, tested engine; genuinely not reachable by any customer, staff, or agent action today. Not a fabricated gap -- verified by exhaustive grep, not assumption.', null, now(), 'claude_session_2026-09-02')
on conflict (capability_key) do nothing;
